/** Reconciles exclusive claims before a Party type or active-state transition commits. */
export const reconcilePartyIdentifierClaims = (
  transaction: Pick<PartyTransaction, 'select' | 'insert' | 'delete'>,
  tenantId: string,
  partyId: string,
  nextPartyType: PartyType,
) =>
  Effect.gen(function* reconcileClaims() {
    yield* lockTenantIdentityWrites(transaction, tenantId);
    const now = yield* DateTime.nowAsDate;
    const identifierRows = yield* attempt(() =>
      transaction
        .select()
        .from(partyOfficialIdentifiers)
        .where(
          and(
            eq(partyOfficialIdentifiers.tenantId, tenantId),
            eq(partyOfficialIdentifiers.partyId, partyId),
            eq(partyOfficialIdentifiers.state, 'ACTIVE'),
            eq(partyOfficialIdentifiers.isCurrent, true),
            lte(partyOfficialIdentifiers.validFrom, now),
            or(isNull(partyOfficialIdentifiers.validTo), gt(partyOfficialIdentifiers.validTo, now)),
          ),
        )
        .for('update'),
    );
    const eligibleIdentifiers = identifierRows
      .filter((row) => row.namespace === (row.identifierTypeKey === 'ICO' ? 'CZ:ICO' : 'CZ:DIC'))
      .map((row) => ({
        // SAFETY: The owner-local identifier type CHECK admits only the supported identifier codes.
        identifierType: row.identifierTypeKey as NormalizedOfficialIdentifier['identifierType'],
        // SAFETY: The preceding filter admits only the canonical namespace for the stored type.
        namespace: row.namespace as NormalizedOfficialIdentifier['namespace'],
        normalizedValue: row.normalizedValue,
        // SAFETY: The owner-local verification CHECK admits only the declared verification states.
        verification: row.verificationState as NormalizedOfficialIdentifier['verification'],
      }))
      .filter((identifier) =>
        qualifiesForExclusiveClaim(identifier, nextPartyType, MATCH_RULE_VERSION),
      );
    const uniqueIdentifiers = [
      ...new Map(
        eligibleIdentifiers.map((identifier) => [
          [identifier.identifierType, identifier.namespace, identifier.normalizedValue].join(
            '\u0000',
          ),
          identifier,
        ]),
      ).values(),
    ];
    const resolvedClaims = yield* lockAndResolveClaims(transaction, tenantId, uniqueIdentifiers);
    const claimOwnership = classifyUnarchiveClaimOwners(partyId, resolvedClaims);
    if (claimOwnership._tag !== 'available') {
      return claimOwnership;
    }

    const ownedClaims = yield* attempt(() =>
      transaction
        .select()
        .from(partyIdentifierClaims)
        .where(
          and(
            eq(partyIdentifierClaims.tenantId, tenantId),
            eq(partyIdentifierClaims.partyId, partyId),
          ),
        )
        .for('update'),
    );
    const eligibleKeys = new Set(
      uniqueIdentifiers.map((identifier) =>
        JSON.stringify([
          identifier.identifierType,
          identifier.namespace,
          identifier.normalizedValue,
        ]),
      ),
    );
    const releasedClaimIds = ownedClaims
      .filter(
        (claim) =>
          !eligibleKeys.has(
            JSON.stringify([claim.identifierTypeKey, claim.namespace, claim.normalizedValue]),
          ),
      )
      .map((claim) => claim.identifierClaimId);
    if (releasedClaimIds.length > 0) {
      yield* attempt(() =>
        transaction
          .delete(partyIdentifierClaims)
          .where(
            and(
              eq(partyIdentifierClaims.tenantId, tenantId),
              eq(partyIdentifierClaims.partyId, partyId),
              inArray(partyIdentifierClaims.identifierClaimId, releasedClaimIds),
            ),
          ),
      );
    }

    const identifiersByClaimKey = new Map(
      identifierRows.map((row) => [
        [row.identifierTypeKey, row.namespace, row.normalizedValue].join('\u0000'),
        row,
      ]),
    );
    const unclaimedIdentifiers = resolvedClaims.flatMap(({ claim, partyId: ownerPartyId }) => {
      if (ownerPartyId !== undefined) {
        return [];
      }
      const record = identifiersByClaimKey.get(
        [claim.identifierType, claim.namespace, claim.normalizedValue].join('\u0000'),
      );
      return record === undefined ? [] : [{ claim, record }];
    });
    if (unclaimedIdentifiers.length > 0) {
      yield* attempt(() =>
        transaction.insert(partyIdentifierClaims).values(
          unclaimedIdentifiers.map(({ claim, record }) => ({
            identifierTypeKey: claim.identifierType,
            namespace: claim.namespace,
            normalizedValue: claim.normalizedValue,
            officialIdentifierId: record.officialIdentifierId,
            partyId,
            tenantId,
          })),
        ),
      );
    }

    return { _tag: 'available', eligibleClaimCount: uniqueIdentifiers.length } as const;
  });

interface UpdatePartyIdentityInput {
  readonly actionInvocationId: string;
  readonly displayName?: string | undefined;
  readonly expectedRevision: number;
  readonly externalEvidence?: AresAppliedEvidence | undefined;
  readonly partyId: string;
  readonly partyType?: PartyType | undefined;
  readonly subjectEvidence?: readonly PartySubjectEvidence[] | undefined;
  readonly principalId: string;
  readonly provenanceMethod: string;
  readonly provenanceSource: string;
  readonly validFrom: string;
}

const evaluateTypeEnrichment = (current: PartyRecord, input: UpdatePartyIdentityInput) => {
  if (input.partyType === undefined || input.partyType === current.currentType) {
    return Effect.succeed(null);
  }
  return requirePartySubjectEvidence({
    partyType: input.partyType,
    subjectEvidence: input.subjectEvidence ?? [],
  });
};

const identityUpdateConflicts = (
  current: PartyRecord,
  input: UpdatePartyIdentityInput,
  now: Date,
): boolean =>
  current.revision !== input.expectedRevision ||
  current.archivedAt !== null ||
  instantAsDate(input.validFrom) > now ||
  (input.partyType !== undefined &&
    // SAFETY: The owner-local parties type CHECK admits exactly the PartyType values.
    !isPartyTypeEnrichment(current.currentType as PartyType, input.partyType));

const changedIdentityFactKinds = (current: PartyRecord, input: UpdatePartyIdentityInput) => [
  ...(input.displayName === undefined ? [] : ['DISPLAY_NAME' as const]),
  ...(input.partyType === undefined || input.partyType === current.currentType
    ? []
    : ['PARTY_TYPE' as const]),
];

const invalidIdentityFactInterval = (
  assertions: readonly Pick<typeof partyFactAssertions.$inferSelect, 'validFrom'>[],
  requestedValidFrom: string,
): boolean =>
  assertions.some((assertion) => instantAsDate(requestedValidFrom) < assertion.validFrom);

export const updatePartyIdentityRecord = (
  transaction: Pick<PartyTransaction, 'select' | 'update' | 'insert' | 'delete'>,
  tenantId: string,
  input: UpdatePartyIdentityInput,
) =>
  Effect.gen(function* updateParty() {
    yield* lockTenantIdentityWrites(transaction, tenantId);
    const [current] = yield* attempt(() =>
      transaction
        .select()
        .from(parties)
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, input.partyId)))
        .limit(1)
        .for('update'),
    );
    if (current === undefined) {
      return { _tag: 'not_found' } as const;
    }
    yield* requireCanonicalPartyWriteTarget(transaction, tenantId, input.partyId);
    const now = yield* DateTime.nowAsDate;
    if (identityUpdateConflicts(current, input, now)) {
      return { _tag: 'conflict', value: partyDto(current) } as const;
    }
    const evaluation = yield* evaluateTypeEnrichment(current, input);
    const currentAssertions = yield* attempt(() =>
      transaction
        .select({ validFrom: partyFactAssertions.validFrom })
        .from(partyFactAssertions)
        .where(
          and(
            eq(partyFactAssertions.tenantId, tenantId),
            eq(partyFactAssertions.partyId, input.partyId),
            inArray(partyFactAssertions.factKind, changedIdentityFactKinds(current, input)),
            eq(partyFactAssertions.state, 'ACTIVE'),
            eq(partyFactAssertions.isCurrent, true),
          ),
        )
        .for('update'),
    );
    if (invalidIdentityFactInterval(currentAssertions, input.validFrom)) {
      return { _tag: 'conflict', value: partyDto(current) } as const;
    }
    if (input.partyType !== undefined && input.partyType !== current.currentType) {
      const claims = yield* reconcilePartyIdentifierClaims(
        transaction,
        tenantId,
        input.partyId,
        input.partyType,
      );
      if (claims._tag !== 'available') {
        return { _tag: 'conflict', value: partyDto(current) } as const;
      }
    }
    const changes: Partial<typeof parties.$inferInsert> = {
      revision: current.revision + 1,
      updatedAt: now,
    };
    if (input.displayName !== undefined) {
      changes.currentDisplayName = input.displayName;
    }
    if (input.partyType !== undefined) {
      changes.currentType = input.partyType;
    }
    const [updated] = yield* attempt(() =>
      transaction
        .update(parties)
        .set(changes)
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, input.partyId)))
        .returning(),
    );
    if (updated === undefined) {
      return yield* unavailable();
    }
    const assertions: (typeof partyFactAssertions.$inferInsert)[] = [];
    if (input.displayName !== undefined) {
      assertions.push({
        acceptedByActionInvocationId: input.actionInvocationId,
        acceptedByPrincipalId: input.principalId,
        externalEvidence: input.externalEvidence ?? null,
        factKind: 'DISPLAY_NAME',
        normalizedValue: input.displayName,
        partyId: input.partyId,
        policyVersion: 'party-identity.v1',
        provenanceMethod: input.provenanceMethod,
        provenanceSource: input.provenanceSource,
        tenantId,
        validFrom: instantAsDate(input.validFrom),
      });
    }
    if (input.partyType !== undefined && input.partyType !== current.currentType) {
      assertions.push({
        acceptedByActionInvocationId: input.actionInvocationId,
        acceptedByPrincipalId: input.principalId,
        evidenceEvaluation: evaluation,
        externalEvidence: input.externalEvidence ?? null,
        factKind: 'PARTY_TYPE',
        normalizedValue: input.partyType,
        partyId: input.partyId,
        policyVersion: 'party-identity.v1',
        provenanceMethod: input.provenanceMethod,
        provenanceSource: input.provenanceSource,
        tenantId,
        validFrom: instantAsDate(input.validFrom),
      });
    }
    for (const factKind of changedIdentityFactKinds(current, input)) {
      yield* attempt(() =>
        transaction
          .update(partyFactAssertions)
          .set({ ...endedPartyFactTransition, validTo: instantAsDate(input.validFrom) })
          .where(
            and(
              eq(partyFactAssertions.tenantId, tenantId),
              eq(partyFactAssertions.partyId, input.partyId),
              eq(partyFactAssertions.factKind, factKind),
              eq(partyFactAssertions.state, 'ACTIVE'),
              eq(partyFactAssertions.isCurrent, true),
            ),
          ),
      );
    }
    if (assertions.length > 0) {
      yield* attempt(() => transaction.insert(partyFactAssertions).values(assertions));
    }
    return { _tag: 'found', value: partyDto(updated) } as const;
  });

export const transitionPartyRecord = (
  transaction: Pick<PartyTransaction, 'select' | 'update'>,
  tenantId: string,
  partyId: string,
  expectedRevision: number,
  state: 'ARCHIVED',
) =>
  Effect.gen(function* transitionParty() {
    yield* lockTenantIdentityWrites(transaction, tenantId);
    const [current] = yield* attempt(() =>
      transaction
        .select()
        .from(parties)
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, partyId)))
        .limit(1)
        .for('update'),
    );
    if (current === undefined) {
      return { _tag: 'not_found' } as const;
    }
    yield* requireCanonicalPartyWriteTarget(transaction, tenantId, partyId);
    const archived = current.archivedAt !== null;
    if (current.revision !== expectedRevision || archived === (state === 'ARCHIVED')) {
      return { _tag: 'conflict', value: partyDto(current) } as const;
    }
    const now = yield* DateTime.nowAsDate;
    const [updated] = yield* attempt(() =>
      transaction
        .update(parties)
        .set({
          archivedAt: now,
          revision: current.revision + 1,
          updatedAt: now,
        })
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, partyId)))
        .returning(),
    );
    return updated === undefined
      ? yield* unavailable()
      : ({ _tag: 'found', value: partyDto(updated) } as const);
  });

export const unarchivePartyRecord = (
  transaction: Pick<PartyTransaction, 'select' | 'insert' | 'update' | 'delete'>,
  tenantId: string,
  partyId: string,
  expectedRevision: number,
): Effect.Effect<
  PartyUnarchiveLifecycle,
  PartyAliasResolutionError | PartyAliasWriteRejected | PartyPersistenceUnavailable
> =>
  Effect.gen(function* unarchiveParty() {
    yield* lockTenantIdentityWrites(transaction, tenantId);
    const [current] = yield* attempt(() =>
      transaction
        .select()
        .from(parties)
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, partyId)))
        .limit(1)
        .for('update'),
    );
    if (current === undefined) {
      return { _tag: 'not_found' } as const;
    }
    yield* requireCanonicalPartyWriteTarget(transaction, tenantId, partyId);
    if (current.revision !== expectedRevision || current.archivedAt === null) {
      return { _tag: 'conflict', value: partyDto(current) } as const;
    }

    const openCases = yield* attempt(() =>
      transaction
        .select({ candidateCaseId: duplicateCandidateCases.candidateCaseId })
        .from(duplicateCandidateCaseParties)
        .innerJoin(
          duplicateCandidateCases,
          and(
            eq(duplicateCandidateCases.tenantId, duplicateCandidateCaseParties.tenantId),
            eq(
              duplicateCandidateCases.candidateCaseId,
              duplicateCandidateCaseParties.candidateCaseId,
            ),
          ),
        )
        .where(
          and(
            eq(duplicateCandidateCaseParties.tenantId, tenantId),
            eq(duplicateCandidateCaseParties.partyId, partyId),
            inArray(duplicateCandidateCases.lifecycleState, ['OPEN', 'NEEDS_EVIDENCE']),
          ),
        )
        .limit(1)
        .for('update'),
    );
    if (openCases.length > 0) {
      return {
        _tag: 'review_required',
        caseIds: openCases.map((candidateCase) => candidateCase.candidateCaseId),
        reasonCode: 'OPEN_DUPLICATE_CASE',
      } as const;
    }
    if (current.currentType === 'UNRESOLVED') {
      const reviewedAcceptances = yield* attempt(() =>
        transaction
          .select({ candidateCaseId: duplicateCandidateCases.candidateCaseId })
          .from(duplicateCandidateCases)
          .where(
            and(
              eq(duplicateCandidateCases.tenantId, tenantId),
              eq(duplicateCandidateCases.selectedPartyId, partyId),
              eq(duplicateCandidateCases.lifecycleState, 'RESOLVED'),
              eq(duplicateCandidateCases.resolutionOutcome, 'CREATE_NEW'),
              isNotNull(duplicateCandidateCases.resolutionActionInvocationId),
            ),
          )
          .limit(1),
      );
      if (reviewedAcceptances.length === 0) {
        return { _tag: 'review_required', caseIds: [], reasonCode: 'UNRESOLVED_IDENTITY' } as const;
      }
    }
    const claims = yield* reconcilePartyIdentifierClaims(
      transaction,
      tenantId,
      partyId,
      // SAFETY: The owner-local parties type CHECK admits exactly the PartyType values.
      current.currentType as PartyType,
    );
    if (claims._tag !== 'available') {
      return claims;
    }
    const now = yield* DateTime.nowAsDate;
    const [updated] = yield* attempt(() =>
      transaction
        .update(parties)
        .set({ archivedAt: null, revision: current.revision + 1, updatedAt: now })
        .where(and(eq(parties.tenantId, tenantId), eq(parties.partyId, partyId)))
        .returning(),
    );
    return updated === undefined
      ? yield* unavailable()
      : ({ _tag: 'found', value: partyDto(updated) } as const);
  });

type BlockedUnarchiveCheck = Extract<
  PartyUnarchiveLifecycle,
  { readonly _tag: 'identity_conflict' | 'identity_ambiguous' | 'review_required' }
>;
type UnarchiveTransaction = Parameters<typeof unarchivePartyRecord>[0];

const unarchiveReviewReason = (
  check: BlockedUnarchiveCheck,
): UnarchivePartyBlocked['reasonCode'] => {
  if (check._tag === 'identity_conflict') {
    return 'EXACT_CLAIM_CONFLICT';
  }
  if (check._tag === 'identity_ambiguous') {
    return 'EXACT_CLAIM_AMBIGUOUS';
  }
  return check.reasonCode;
};

const unarchiveReviewParties = (partyId: string, check: BlockedUnarchiveCheck) =>
  [
    ...new Set([
      partyId,
      ...(check._tag === 'identity_conflict' ? [check.conflictingPartyId] : []),
      ...(check._tag === 'identity_ambiguous' ? check.candidatePartyIds : []),
    ]),
  ].toSorted();

const unarchiveReviewExplanations = {
  EXACT_CLAIM_AMBIGUOUS: 'Current exact identifier claims resolve to multiple other Parties.',
  EXACT_CLAIM_CONFLICT: 'A current exact identifier claim belongs to another Party.',
  OPEN_DUPLICATE_CASE: 'Open duplicate identity evidence requires review before reactivation.',
  UNRESOLVED_IDENTITY: 'No retained reviewed acceptance establishes this unresolved identity.',
} as const;

const partyReviewSourceRef = (tenantId: string, partyId: string): string =>
  JSON.stringify(makePartyRef(tenantId, partyId));

const unarchiveCandidateFingerprint = (snapshot: PartyCandidateSnapshot): string =>
  createHash('sha256').update(JSON.stringify(snapshot)).digest('hex');

const unarchiveEvaluationFingerprint = (
  candidateFingerprint: string,
  evaluatedEvidence: readonly PartyEvidenceExplanation[],
  partyIds: readonly string[],
): string =>
  createHash('sha256')
    .update(JSON.stringify({ candidateFingerprint, evaluatedEvidence, partyIds }))
    .digest('hex');

const createUnarchiveReviewCase = (
  transaction: UnarchiveTransaction,
  tenantId: string,
  party: Party,
  check: BlockedUnarchiveCheck,
) =>
  Effect.gen(function* createReviewCase() {
    const existingCaseIds = check._tag === 'review_required' ? check.caseIds : [];
    const [existingCaseId] = existingCaseIds;
    if (existingCaseId !== undefined) {
      const [existing] = yield* attempt(() =>
        transaction
          .select()
          .from(duplicateCandidateCases)
          .where(
            and(
              eq(duplicateCandidateCases.tenantId, tenantId),
              eq(duplicateCandidateCases.candidateCaseId, existingCaseId),
            ),
          )
          .limit(1),
      );
      return existing === undefined ? yield* unavailable() : existing;
    }
    const now = yield* DateTime.nowAsDate;
    const identifiers = yield* attempt(() =>
      transaction
        .select()
        .from(partyOfficialIdentifiers)
        .where(
          and(
            eq(partyOfficialIdentifiers.tenantId, tenantId),
            eq(partyOfficialIdentifiers.partyId, party.partyRef.resourceId),
            eq(partyOfficialIdentifiers.state, 'ACTIVE'),
            eq(partyOfficialIdentifiers.isCurrent, true),
            lte(partyOfficialIdentifiers.validFrom, now),
            or(isNull(partyOfficialIdentifiers.validTo), gt(partyOfficialIdentifiers.validTo, now)),
          ),
        )
        .orderBy(partyOfficialIdentifiers.officialIdentifierId),
    );
    const snapshot: PartyCandidateSnapshot = {
      intent: 'UNARCHIVE',
      names: party.displayName === null ? [] : [party.displayName],
      officialIdentifiers: identifiers.map((identifier) => ({
        // SAFETY: Owner-local CHECK constraints restrict identifier and verification types.
        identifierTypeKey: identifier.identifierTypeKey as 'ICO' | 'CZ_DIC',
        namespace: identifier.namespace,
        normalizedValue: identifier.normalizedValue,
        // SAFETY: Owner-local CHECK constraints restrict verification types.
        verificationState: identifier.verificationState as 'VERIFIED' | 'UNVERIFIED' | 'REJECTED',
      })),
      partyType: party.partyType,
      policyVersion: MATCH_RULE_VERSION,
      provenance: { method: 'UNARCHIVE_CANONICAL_RECHECK', source: 'party.registry' },
      sourceRecordRefs: [partyReviewSourceRef(tenantId, party.partyRef.resourceId)],
      validFrom: party.updatedAt,
    };
    const reasonCode = unarchiveReviewReason(check);
    const partyIds = unarchiveReviewParties(party.partyRef.resourceId, check);
    const explanation: PartyEvidenceExplanation = {
      evidenceRefs: partyIds.map((id) => partyReviewSourceRef(tenantId, id)),
      outcome: 'AMBIGUOUS',
      reason: unarchiveReviewExplanations[reasonCode],
      ruleKey: `party-unarchive-review.v1:${reasonCode}`,
    };
    const evaluatedEvidence: readonly PartyEvidenceExplanation[] = [explanation];
    const candidateFingerprint = unarchiveCandidateFingerprint(snapshot);
    const evaluationFingerprint = unarchiveEvaluationFingerprint(
      candidateFingerprint,
      evaluatedEvidence,
      partyIds,
    );
    const [open] = yield* attempt(() =>
      transaction
        .select()
        .from(duplicateCandidateCases)
        .where(
          and(
            eq(duplicateCandidateCases.tenantId, tenantId),
            eq(duplicateCandidateCases.evaluationFingerprint, evaluationFingerprint),
            eq(duplicateCandidateCases.matchRuleVersion, MATCH_RULE_VERSION),
            inArray(duplicateCandidateCases.lifecycleState, ['OPEN', 'NEEDS_EVIDENCE']),
          ),
        )
        .limit(1),
    );
    if (open !== undefined) {
      return open;
    }
    const [prior] = yield* attempt(() =>
      transaction
        .select()
        .from(duplicateCandidateCases)
        .where(
          and(
            eq(duplicateCandidateCases.tenantId, tenantId),
            eq(duplicateCandidateCases.candidateFingerprint, candidateFingerprint),
            eq(duplicateCandidateCases.matchRuleVersion, MATCH_RULE_VERSION),
          ),
        )
        .orderBy(desc(duplicateCandidateCases.createdAt))
        .limit(1),
    );
    const [created] = yield* attempt(() =>
      transaction
        .insert(duplicateCandidateCases)
        .values({
          candidateFingerprint,
          candidateSnapshot: snapshot,
          evaluatedEvidence,
          evaluationFingerprint,
          matchRuleVersion: MATCH_RULE_VERSION,
          priorCandidateCaseId: prior?.candidateCaseId ?? null,
          tenantId,
        })
        .returning(),
    );
    if (created === undefined) {
      return yield* unavailable();
    }
    yield* attempt(() =>
      transaction.insert(duplicateCandidateCaseParties).values(
        partyIds.map((id, index) => ({
          candidateCaseId: created.candidateCaseId,
          evidenceExplanation: explanation,
          partyId: id,
          rank: index + 1,
          tenantId,
        })),
      ),
    );
    return created;
  });

/** A blocked recheck is a committed review result, never a rollback-only domain rejection. */
export const unarchivePartyWithReview = (
  transaction: UnarchiveTransaction,
  tenantId: string,
  partyId: string,
  expectedRevision: number,
  actionInvocationId: string,
) =>
  Effect.gen(function* unarchiveWithReview() {
    const check = yield* unarchivePartyRecord(transaction, tenantId, partyId, expectedRevision);
    if (check._tag === 'found' || check._tag === 'not_found' || check._tag === 'conflict') {
      return check;
    }
    const lookup = yield* findPartyRecord(transaction, tenantId, partyId);
    if (lookup._tag === 'not_found') {
      return yield* unavailable();
    }
    const candidateCase = yield* createUnarchiveReviewCase(
      transaction,
      tenantId,
      lookup.value,
      check,
    );
    const [decision] = yield* attempt(() =>
      transaction
        .insert(partyMatchDecisions)
        .values({
          actionInvocationId,
          candidateCaseId: candidateCase.candidateCaseId,
          candidateFingerprint: candidateCase.candidateFingerprint,
          evidenceExplanation: candidateCase.evaluatedEvidence,
          matchRuleVersion: candidateCase.matchRuleVersion,
          operation: 'LIFECYCLE',
          outcome: 'AMBIGUOUS',
          tenantId,
        })
        .returning(),
    );
    if (decision === undefined) {
      return yield* unavailable();
    }
    const value: UnarchivePartyBlocked = {
      caseRef: makeDuplicateCandidateCaseRef(tenantId, candidateCase.candidateCaseId),
      decisionRef: makePartyMatchDecisionRef(tenantId, decision.matchDecisionId),
      outcome: 'BLOCKED',
      party: lookup.value,
      reasonCode: unarchiveReviewReason(check),
    };
    return { _tag: 'blocked', value } as const;
  });
